// The TVM-FFI faces of the elem AOT kernels: per-kernel typed functions that marshal
// TensorView arguments and int64 scalars onto the packed-launch C ABI and launch on the
// current NPU stream. Generated by tools/aot_glue_gen.py from the generator manifests
// (tools/generate.py's own ``launcher_abi`` record); the python envelopes that call these
// faces own the validation - the ctypes bindings they replace had no checks of their own
// either. The declarations follow the packed-launch contract: void* per tensor, int64 per
// scalar, the stream last (the aarch64 C ABI passes pointers type-agnostically; the
// generated host code spells the same parameters with its typed pointers).
#include "common/aot_glue.h"

#include <cstdint>

namespace xinfer::aot::elem_glue {
using xinfer::aot::glue::TensorView;

extern "C" {
int32_t xinfer_aot_qksq_c6144_call(void*, void*, int64_t, void* stream);
const char* xinfer_aot_qksq_c6144_get_last_error();
}

void qksq_c6144(TensorView sq, TensorView x, int64_t rows) {
  xinfer::aot::glue::Launch("qksq_c6144", xinfer_aot_qksq_c6144_call,
                            xinfer_aot_qksq_c6144_get_last_error, sq, x, rows);
}
TVM_FFI_DLL_EXPORT_TYPED_FUNC(qksq_c6144, xinfer::aot::elem_glue::qksq_c6144);

extern "C" {
int32_t xinfer_aot_rawsq_r128_call(void*, void*, int64_t, void* stream);
const char* xinfer_aot_rawsq_r128_get_last_error();
}

void rawsq_r128(TensorView sq, TensorView x, int64_t rows) {
  xinfer::aot::glue::Launch("rawsq_r128", xinfer_aot_rawsq_r128_call,
                            xinfer_aot_rawsq_r128_get_last_error, sq, x, rows);
}
TVM_FFI_DLL_EXPORT_TYPED_FUNC(rawsq_r128, xinfer::aot::elem_glue::rawsq_r128);

}  // namespace xinfer::aot::elem_glue
